import unittest,json,math
from datetime import date
from pathlib import Path
from ablate import replay,metrics,ms,permitted
from analyse_readiness import london
P=Path('/workspace/jiaoyi-ablation-18490')
class Tests(unittest.TestCase):
 def entry(self,side='long'):
  return {'fill':100.,'initial_r':10.,'side':side,'digits':2,'volume':100,'broker_tp_distance':13.8,'entered_at':'2024-11-04T07:00:00Z','session_end':'2024-11-04T11:00:00Z'}
 def quotes(self,prices,side='long'):
  t=ms(self.entry()['entered_at'])
  return [{'at':t+1000*i,'bid':round(p*100)if side=='long'else round((p-.02)*100),'ask':round((p+.02)*100)if side=='long'else round(p*100),'fresh':True,'gap_before':False}for i,p in enumerate(prices)]
 def run_path(self,prices,offset,side='long'):
  e=self.entry(side);return replay(e,self.quotes(prices,side),offset,'forced',ms(e['session_end']))
 def test_trigger_is_exactly_one_r_both_sides(self):
  for side,prices in [('long',[100,109.99,100]),('short',[100,90.01,100])]:
   o=self.run_path(prices,.05,side);self.assertEqual(o['trail_proposals'],0);self.assertEqual(o['trail_applied'],0)
 def test_next_quote_amend_and_gap_fill_both_sides(self):
  for side,prices,stop in [('long',[100,110,111,100.20],100.30),('short',[100,90,89,99.80],99.70)]:
   o=self.run_path(prices,.03,side);self.assertEqual(o['trail_applied'],1);self.assertAlmostEqual(o['active_stop'],stop)
   self.assertEqual(o['fills'][0]['reason'],'gap_through_stop');self.assertAlmostEqual(o['scenario_gross_r'],.02)
 def test_pending_amend_cannot_retroactively_rescue(self):
  o=self.run_path([100,110,89],.05);self.assertEqual(o['trail_applied'],0);self.assertAlmostEqual(o['scenario_gross_r'],-1.1)
 def test_can_expose_early_runner_cut(self):
  base=self.run_path([100,110,111,100.20,114],0);new=self.run_path([100,110,111,100.20,114],.03)
  self.assertEqual(base['fills'][0]['reason'],'broker_take_profit');self.assertEqual(new['fills'][0]['reason'],'gap_through_stop')
 def test_old_bracket_wins_and_offset_rounds_toward_entry(self):
  o=self.run_path([100,110,114],.05);self.assertEqual(o['fills'][0]['reason'],'broker_take_profit')
  e=self.entry();e['initial_r']=.13;e['broker_tp_distance']=.18
  q=self.quotes([100,100.13,100.14,100]);o=replay(e,q,.05,'forced',ms(e['session_end']))
  self.assertEqual(o['actual_offset_r'],0)
 def test_calendar_dst_counts_and_whole_bar_bounds(self):
  for ds,n in [('2026-10-30',390),('2026-11-02',450)]:
   a,b=london(date.fromisoformat(ds));self.assertEqual((b-a).total_seconds()/60,n)
  d=json.loads((P/'readiness-analysis.json').read_text());self.assertEqual(len(d['london_rows']),24)
  self.assertTrue(all(r['calendar_maximum_endpoints']==r['recorded_endpoint_count']==12 for r in d['london_rows']))
 def test_research_seal_and_boundary_exclusions(self):
  for a,b in [('2025-08-18T23:45:00Z','2025-08-19T00:15:00Z'),('2025-09-05T23:30:00Z','2025-09-06T00:00:00Z'),('2025-10-24T00:00:00Z','2025-10-24T00:30:00Z')]:self.assertFalse(permitted(ms(a),ms(b)))
  self.assertTrue(permitted(ms('2024-11-04T07:00:00Z'),ms('2024-11-04T11:00:05Z')))
 def test_metrics_costs_rolling20_and_native_parity(self):
  rows=[{'episode_id':str(i),'date':'2024-11-04','symbol':'X','exit_at':str(i).zfill(3),'net_r':1 if i<15 else-1,'net_usd':1 if i<15 else-1}for i in range(20)]
  m=metrics(rows);self.assertEqual(m['rolling20_pass_rate'],1);self.assertEqual(m['profit_factor'],3);self.assertEqual(m['payoff_ratio'],1);self.assertEqual(m['closed_curve_max_drawdown_r'],5)
  self.assertIsNone(metrics(rows[:7])['rolling20_pass_rate'])
  d=json.loads((P/'offline-results.json').read_text());self.assertEqual(d['native_baseline_parity'],35);self.assertEqual(d['python_exit_baseline_parity'],14)
  for t in d['trades']:
   for o in t['outcomes'].values():
    for bps,c in o['costs'].items():
     if c['net_r']is not None:
      e=t['entry'];f=o['fills'][0];self.assertAlmostEqual(c['net_r'],o['scenario_gross_r']-(e['fill']+f['price'])*float(bps)/10000/e['initial_r'])
      self.assertAlmostEqual(c['net_usd'],c['net_r']*e['initial_r']*e['volume']/100)
  self.assertEqual(d['crypto_evaluable_episodes'],0);self.assertFalse(d['requested_active_policy_tested'])
if __name__=='__main__':unittest.main(verbosity=2)
